## 3. Result-Generation Logic (form data → recommendation)

The recommendation is computed by the inline `evaluate()` function defined directly inside the Compass page (not in a separate lib file).

Source: `client/src/pages/VaricocelectomyCompass.tsx`

```typescript
type VGrade = "I" | "II" | "III" | "subclinical";
interface VCInputs {
  grade: VGrade;
  bilateral: boolean;
  totalMotileCount: number;
  spermConcentration: number;
  progressiveMotility: number;
  morphologyKruger: number;
  fshLevel: number;
  testosteroneLevel: number;
  testisVolumeDiff: number; // % difference
  partnerAge: number;
  partnerFertilityNormal: boolean;
  infertilityDuration: number; // months
  painPresent: boolean;
  adolescent: boolean;
  priorVaricocelectomy: boolean;
}

const defaultInputs: VCInputs = {
  grade: "II", bilateral: false, totalMotileCount: 0, spermConcentration: 0,
  progressiveMotility: 0, morphologyKruger: 0, fshLevel: 0, testosteroneLevel: 0,
  testisVolumeDiff: 0, partnerAge: 0, partnerFertilityNormal: true,
  infertilityDuration: 0, painPresent: false, adolescent: false, priorVaricocelectomy: false,
};

function evaluate(inputs: VCInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Schlegel PN, et al. Diagnosis and treatment of infertility in men: AUA/ASRM guideline. J Urol. 2021;205(2):397-398.",
    "Baazeem A, et al. Varicocele and male factor infertility treatment: a new meta-analysis and review of the role of varicocele repair. Eur Urol. 2011;59(5):796-808.",
    "Nork JJ, et al. The AUA/ASRM varicocele guideline: implications for the practicing urologist. Urol Pract. 2022;9(1):1-8.",
    "Kirby EW, et al. Microsurgical varicocelectomy vs. embolization: a meta-analysis. J Urol. 2016;196(5):1371-1379.",
    "EAU Guidelines on Male Infertility. European Association of Urology. 2024.",
  ];

  let recommendation = "not_indicated";
  let procedure = "Observation";
  let cor = "III";
  let loe = "B";

  // AUA/ASRM 2021 indications
  const abnormalSemen = inputs.spermConcentration < 15 || inputs.progressiveMotility < 32 || inputs.morphologyKruger < 4 || inputs.totalMotileCount < 9;
  const palpableVaricocele = inputs.grade === "I" || inputs.grade === "II" || inputs.grade === "III";
  const clinicallySignificant = palpableVaricocele && inputs.grade !== "subclinical";

  if (inputs.adolescent) {
    if (inputs.testisVolumeDiff >= 20) {
      recommendation = "indicated";
      procedure = "Microsurgical Varicocelectomy";
      cor = "IIa"; loe = "B";
      rationale.push("Adolescent with ≥20% testicular volume differential: AUA/ASRM recommend repair to prevent progressive testicular injury.");
    } else {
      recommendation = "consider";
      procedure = "Observation with annual semen analysis";
      rationale.push("Adolescent with <20% volume differential: observation with annual follow-up is appropriate.");
    }
  } else if (inputs.painPresent && clinicallySignificant) {
    recommendation = "consider";
    procedure = "Microsurgical Varicocelectomy (pain indication)";
    cor = "IIb"; loe = "C";
    rationale.push("Varicocele-associated scrotal pain: surgical repair is reasonable when pain is refractory to conservative management.");
  } else if (clinicallySignificant && abnormalSemen && inputs.infertilityDuration >= 12) {
    recommendation = "indicated";
    procedure = "Microsurgical Varicocelectomy (subinguinal approach preferred)";
    cor = "I"; loe = "A";
    rationale.push("Palpable varicocele + abnormal semen parameters + ≥12 months infertility: AUA/ASRM Grade A recommendation for repair.");
    rationale.push("Meta-analysis (Baazeem 2011): varicocelectomy improves sperm concentration, motility, and morphology with OR 2.87 for spontaneous pregnancy.");
  } else if (inputs.grade === "subclinical") {
    recommendation = "not_indicated";
    procedure = "No repair — subclinical varicocele";
    cor = "III"; loe = "A";
    rationale.push("Subclinical varicocele: AUA/ASRM explicitly recommend against repair — no evidence of benefit.");
    warnings.push("Subclinical varicoceles detected only on ultrasound should NOT be repaired per AUA/ASRM guidelines.");
  } else {
    recommendation = "not_indicated";
    procedure = "Observation";
    rationale.push("Criteria for repair not met: requires palpable varicocele + abnormal semen + ≥12 months infertility (or pain/adolescent indications).");
  }

  if (inputs.partnerAge > 37) {
    warnings.push(`Partner age ${inputs.partnerAge}: consider IVF/ICSI as concurrent or alternative strategy given diminished ovarian reserve.`);
  }
  if (inputs.fshLevel > 10) {
    warnings.push(`Elevated FSH (${inputs.fshLevel}): suggests primary spermatogenic impairment; varicocelectomy benefit may be limited.`);
  }
  if (inputs.priorVaricocelectomy) {
    warnings.push("Prior varicocelectomy: recurrence repair is appropriate if palpable varicocele recurs with abnormal semen.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
